5: 
6: #[test]
7: fn mean_of_a_partial_window() {
8:     let mut w = Window::new(4);
9:     w.push(2);
10:     w.push(4);
11:     assert_eq!(w.mean(), 3);
12: }
13: 
14: #[test]
15: fn values_come_back_oldest_first() {
16:     let mut w = Window::new(3);
17:     w.push(1);
18:     w.push(2);
19:     assert_eq!(w.values(), vec![1, 2]);
20: }
21: 
22: #[test]
23: fn a_full_window_evicts_the_oldest() {
24:     let mut w = Window::new(3);
25:     for v in [1, 2, 3, 4] {
26:         w.push(v);
27:     }
28:     assert_eq!(w.values(), vec![2, 3, 4]);
29:     assert_eq!(w.mean(), 3);
30: }

