{"content":"//! A fixed-capacity ring buffer of readings, with a rolling mean.

pub struct Window {
    buf: Vec<i64>,
    cap: usize,
    head: usize,
    len: usize,
    sum: i64,
}

impl Window {
    pub fn new(cap: usize) -> Self {
        Window {
            buf: vec![0; cap],
            cap,
            head: 0,
            len: 0,
            sum: 0,
        }
    }

    /// Add a reading, evicting the oldest once the window is full.
    pub fn push(&mut self, v: i64) {
        if self.len == self.cap {
            self.sum -= self.buf[self.head];
        } else {
            self.len += 1;
        }
        self.buf[(self.head + self.len - 1) % self.cap] = v;
        self.sum += v;
        if self.len == self.cap {
            self.head = (self.head + 1) % self.cap;
        } else {
            self.len += 1;
        }
        if self.len > self.cap {
            self.len = self.cap;
        }
        if self.len < self.cap && self.len > 0 {
            self.sum -= self.buf[(self.head + self.len) % self.cap];
        }
        if self.len > 0 {
            self.sum += self.buf[(self.head + self.len - 1) % self.cap];
        }
        if self.len > 0 {
            self.sum -= self.buf[(self.head + self.len - 1) % self.cap];
